layer.css:
@import url("https://fonts.googleapis.com/css2?family=Mulish:ital,wght@0,200..1000;1,200..1000&display=swap");
[data-ryt="pitch"] { color: rgb(85, 85, 85); border-left: 4px solid rgb(71, 177, 219); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 17.6px; font-weight: 400; font-style: italic; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(85, 85, 85); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 26.4px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); background-color: var(--ryt-bg); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: #4398b9; border-bottom: 1px solid rgba(0, 0, 0, 0); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: -0.057px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(71, 177, 219); text-decoration-thickness: auto; text-underline-offset: auto; transition: border-color 0.2s; border-top: none; border-right: none; border-left: none }
[data-ryt="hero"] h1 { color: var(--ryt-accent); font-family: var(--ryt-font-heading); font-size: 44px; font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: -0.88px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-accent); border-bottom: 3px solid rgb(71, 177, 219); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 22px; font-weight: 700; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: border-color 0.2s; border-top: none; border-right: none; border-left: none }
[data-ryt="nav"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 15px; font-weight: 600; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: color 0.2s }
[data-ryt="category"], [data-ryt="tags"] li { color: var(--ryt-text); background-color: rgb(249, 249, 249); border-top: 1px solid rgb(224, 224, 224); border-right: 1px solid rgb(224, 224, 224); border-bottom: 1px solid rgb(224, 224, 224); border-left: 1px solid rgb(224, 224, 224); border-radius: 3px; font-family: var(--ryt-font-heading); font-weight: 500; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 2px; padding-right: 8px; padding-bottom: 2px; padding-left: 8px; transition: all }
[data-ryt="review"] { color: rgb(85, 85, 85); font-family: var(--ryt-font-heading); font-size: 17px; font-weight: 300; font-style: normal; line-height: 1.588; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(85, 85, 85); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 13px; font-weight: 600; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.2s; position: relative }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 19px; font-weight: 700; font-style: normal; line-height: 1.4; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.2s }
[data-ryt="rec-card"] [data-ryt="title"] a::before { content: ""; display: block; position: absolute; width: 14px; height: 14px; color: var(--ryt-accent); background-color: var(--ryt-bg); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-top: 3px solid rgb(71, 177, 219); border-right: 3px solid rgb(71, 177, 219); border-bottom: 3px solid rgb(71, 177, 219); border-left: 3px solid rgb(71, 177, 219); border-radius: 50%; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: 0.2s; -webkit-text-fill-color: var(--ryt-accent); top: 32px; left: 94px }
[data-ryt="brand"]:hover { border-bottom-color: #47b1db }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { border-bottom-color: #47b1db }
